                    "propertyValues": {
                        "delimiter": {
                            "type": "JSON_LITERAL",
                            "value": ","
                        },
                        "items": {
                            "script": {
                                "apiVersion": "1.0.0",
                                "controllerElementId": null,
                                "inlineScript": "/**\n * @param {params} params\n * @param {api} params.api\n * @param {any} params.imports\n */\nfunction evaluateProperty({\n    api\n}) {\n    if (api.data.delete_entity_types.output && api.data.delete_entity_types.output[\"deleted\"]) {\n        const items = [];\n        let associatedItems = api.data.delete_entity_types.output[\"deleted\"];\n        let keys = Object.keys(associatedItems);\n\n        for (let i = 0; i < keys.length; i++) {\n            var link = associatedItems[keys[i]].link;\n            var title = associatedItems[keys[i]].label;\n\n            var item = {\n                label: associatedItems[keys[i]].label,\n                value: {\n                    type: 'text-link',\n                    label: associatedItems[keys[i]].number,\n                    href: link,\n                    underlined: true,\n                    opensWindow: true\n                }\n            };\n\n            items.push(item);\n        }\n        return items;\n    }\n}",
                                "scriptSysId": null,
                                "target": null
                            },
                            "type": "CLIENT_TRANSFORM_SCRIPT"
                        },
                        "size": {
                            "type": "JSON_LITERAL",
                            "value": "sm"
                        }
                    },
                    "slot": null,
                    "styles": null
