                        },
                        "items": {
                            "script": {
                                "apiVersion": "2.0.0",
                                "controllerElementId": null,
                                "inlineScript": "/**\n * @param {params} params\n * @param {api} params.api\n * @param {any} params.imports\n */\nfunction evaluateProperty({\n    api\n}) {\n    if (api.data.delete_entity_types.output && api.data.delete_entity_types.output[\"deactivated-retired\"]) {\n        const items = [];\n        let associatedItems = api.data.delete_entity_types.output[\"deactivated-retired\"];\n        let keys = Object.keys(associatedItems);\n        var workspaceURL = api.data.delete_entity_types.output[\"pageURL\"];\n        \n        for (let i = 0; i < keys.length; i++) {\n            var link = associatedItems[keys[i]].link;\n            var title = associatedItems[keys[i]].label;\n            var url = link;\n            if(link.includes(\"sysparm_query=\")){\n                var query = link.substr(link.indexOf('sysparm_query=') + 'sysparm_query='.length);\n                url = `/now/${workspaceURL}/list-view/${keys[i]}/params/listTitle/${title}/query/${query}`; \n            }\n            \n            var item = {\n                label: associatedItems[keys[i]].label,\n                value: {\n                    type: 'text-link',\n                    label: associatedItems[keys[i]].number,\n                    href: url,\n                    underlined: true,\n                    opensWindow: true\n                }\n            };\n            items.push(item);\n        }\n        return items;\n    }\n}",
                                "scriptSysId": "d095340b47fb6a1097744049116d43f2",
                                "target": null
                            },
                            "type": "CLIENT_TRANSFORM_SCRIPT"
